/**
 * City meeting recaps (City of Fairfax, Manassas). Same rules as src/content/loudoun-recaps.ts:
 * decisions and votes ONLY from official minutes (Fairfax: Granicus minutes; Manassas City Council:
 * manassascity.granicus.com minutes; Manassas schools: BoardDocs minutes/motions). Until minutes are
 * posted keep official.votesPosted false. Never infer a vote from video or transcript.
 * Renders at /cities/{city}/recaps/{slug}.
 */
import { sortRecapsNewestFirst } from "./recap-sort";
import type { LoudounRecap } from "./loudoun-recaps";
import type { CityVenueId } from "./cities";
import FILL_JSON from "./city-recap-fill.json";
import { HC_RECAPS } from "./city-recaps-hc";

/** Generated by scripts/fairfax-recap-fill.py from official Granicus minutes/agendas (+ video index / transcript for timing). */
type Fill = {
  decisions?: CityRecap["decisions"];
  noVotesRecorded?: boolean;
  agenda?: CityRecap["agenda"];
  moments?: (CityRecap["moments"][number] & { how?: string })[];
  /** Extra official-record links (e.g. Albemarle ESB agenda); appended, never replacing. */
  links?: { label: string; href: string }[];
};
const FILL = FILL_JSON as Record<string, Fill>;
const FILLER_MOMENTS = new Set(["Early agenda business.", "Mid-meeting discussion.", "Later agenda business."]);

function applyFill(r: CityRecap): CityRecap {
  const f = FILL[r.slug];
  if (!f) return r;
  const decisions = r.decisions.length ? r.decisions : (f.decisions ?? []);
  const agenda = r.agenda.length ? r.agenda : (f.agenda ?? []);
  let moments = r.moments;
  if (f.moments?.length) {
    const kept = r.moments.filter((m) => !FILLER_MOMENTS.has(m.label));
    const add = f.moments
      .filter((m) => !kept.some((k) => Math.abs(k.seconds - m.seconds) < 45))
      .map(({ how: _how, ...m }) => m);
    moments = [...kept, ...add].sort((a, b) => a.seconds - b.seconds);
  }
  const votesPosted = r.official.votesPosted || decisions.length > 0;
  const noVotesRecorded = !decisions.length && !!f.noVotesRecorded;
  return {
    ...r,
    decisions,
    agenda,
    moments,
    noVotesRecorded,
    official: {
      ...r.official,
      links: [...r.official.links, ...(f.links ?? []).filter((l) => !r.official.links.some((x) => x.href === l.href))],
      votesPosted,
      note: votesPosted
        ? "Actions and tallies below are copied from the official minutes linked here. Nothing is inferred from video or transcript."
        : noVotesRecorded
          ? "The official minutes for this meeting record no votes (discussion only)."
          : r.official.note,
    },
  };
}

export type CityRecap = Omit<LoudounRecap, "venue"> & { venue: CityVenueId; noVotesRecorded?: boolean };

